// Базовый набор — всё с need 0, кроме поездок (они по ситуации).
export const isBase = g => g.need === 0 && g.cat !== "travel";
export const orderWeek = g => Math.max(1, g.need - LEAD);
// Сезонные вещи (sea:[с месяца, по месяц]) вне сезона в «Пора заказать» и пушах не предлагаем — они остаются во «Всём списке».
export const inSeason = (g, iso) => { if (!g.sea) return true; const m = Number(iso.slice(5, 7)); return m >= g.sea[0] && m <= g.sea[1]; };
export const gearForWeek = n => GEAR.filter(g => g.need >= 4 && orderWeek(g) === n);
