export function remindersFor(birth, day){
  const wk = Math.max(1, ageOf(birth, day).week); if (wk > 52) return [];
  return REMIND.flatMap(r => { const s = r.st.find(([a, b]) => wk >= a && wk <= b); return s ? [{id:r.id, ic:r.ic, x:s[2], pts:s[3]}] : []; });
}
