// этапы, которые можно включить раньше плана (еду — нет: прикорм по готовности и с педиатром)
export const earlyOk = id => !["feed", "allerg", "cup"].includes(id);
// этап рутины, к которому относится вещь: {id, a — неделя начала, x — название этапа}
export function gearStage(g){
  if (!g?.rt) return null;
  const [id, a] = g.rt.split(":"), s = ROUTINE.find(r => r.id === id)?.st.find(st => st[0] === Number(a));
  return s ? {id, a:Number(a), x:s[2], how:s[3]} : null;
}
export function routineForWeek(n){
  const out=[];
  for(const r of ROUTINE){ const s=r.st.find(([a,b])=>n>=a&&n<=b); if(s) out.push({id:r.id,cat:r.cat,x:s[2],how:s[3],every:s[4]}); }
  return out;
}
// ---------- Своя рутина семьи ----------
// cfg (families.routine): {own:[{id:"u<число>", x, how, from:"ГГГГ-ММ-ДД", until:"ГГГГ-ММ-ДД"|null}], adj:{<id пункта>: {off:1} | {until?:"ГГГГ-ММ-ДД", early?:неделя этапа, from?:"ГГГГ-ММ-ДД"}}}
// early/from — этап, начинающийся с недели early, показываем уже с даты from (вещь купили раньше)
// own — свои пункты (until null — бессрочно); adj — сроки встроенных пунктов: off — не показывать, until — показывать по эту дату
// (раньше плана — сокращение; позже — продление последнего этапа).
const isoAdd = (iso, k) => new Date(Date.parse(iso + "T00:00:00Z") + k * 864e5).toISOString().slice(0, 10);
export const routineSpan = id => { const st = ROUTINE.find(r => r.id === id)?.st || []; return st.length ? [Math.min(...st.map(s => s[0])), Math.max(...st.map(s => s[1]))] : null; };
// последний день недели жизни n (неделя 1 — дни 0–6)
export const weekEndDate = (birth, n) => isoAdd(birth, n * 7 - 1);
export const weekStartDate = (birth, n) => isoAdd(birth, (n - 1) * 7);
export function routineFor(birth, day, cfg){
  const adj = cfg?.adj || {}, out = [];
  const {week, days} = ageOf(birth, day), wk = Math.max(1, week);
  if (wk <= 52) for (const r of ROUTINE) {
    const a = adj[r.id]; if (a?.off || (a?.until && day > a.until)) continue;
    let s = r.st.find(([x, y]) => wk >= x && wk <= y);
    if (!s && a?.until && wk > routineSpan(r.id)[1]) s = r.st[r.st.length - 1];   // продлили сверх плана — последний этап
    if (a?.early && day >= a.from && wk < a.early) s = r.st.find(([x]) => x === a.early) || s;   // включили этап раньше плана (вещь уже есть)
    if (s && s[4] && days % s[4]) continue;                                         // «раз в N дней» — только в свои дни
    if (s) out.push({id:r.id, cat:r.cat, x:s[2], how:s[3], every:s[4]});
  }
  for (const o of cfg?.own || []) if (day >= o.from && (!o.until || day <= o.until)) out.push({id:o.id, cat:"own", x:o.x, how:o.how || "", own:true});
  return out;
}
// проверка и нормализация cfg с клиента (сервер хранит только то, что прошло)
export function cleanRoutineCfg(c){
  const iso = v => typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null;
  const txt = (v, n) => String(v ?? "").replace(/\s+/g, " ").trim().slice(0, n);
  const own = (Array.isArray(c?.own) ? c.own : []).slice(0, 40).map(o => ({id:/^u\d{1,16}$/.test(o?.id) ? o.id : null, x:txt(o?.x, 80), how:txt(o?.how, 160), from:iso(o?.from), until:iso(o?.until)}))
    .filter(o => o.id && o.x && o.from);
  const adj = {};
  for (const [k, v] of Object.entries(c?.adj || {})) if (ROUTINE.some(r => r.id === k)) {
    if (v?.off) { adj[k] = {off:1}; continue; }
    const o = {};
    if (iso(v?.until)) o.until = v.until;
    if (earlyOk(k) && iso(v?.from) && ROUTINE.find(r => r.id === k).st.some(s => s[0] === v?.early && s[0] > 1)) { o.early = v.early; o.from = v.from; }
    if (Object.keys(o).length) adj[k] = o;
  }
  return {own, adj};
}

