// Возраст: полные месяцы и дни по календарю, день жизни, неделя жизни.
export function ageOf(birthISO, todayISO){
  const [by,bm,bd]=birthISO.split("-").map(Number), [ty,tm,td]=todayISO.split("-").map(Number);
  const b=Date.UTC(by,bm-1,bd), t=Date.UTC(ty,tm-1,td);
  const days=Math.round((t-b)/864e5);
  let months=(ty-by)*12+(tm-bm); if(td<bd) months--;
  if(months<0) months=0;
  const anchor=Date.UTC(by,bm-1+months,bd);
  const rest=Math.round((t-anchor)/864e5);
  return {days, months, rest, week: Math.floor(days/7)+1, dayOfWeek: days%7};
}
export const flagsFor = months => FLAGS.find(f => months>=f.from && months<f.to);
// «Совет дня»: подходящий по возрасту (неделя from..to), сезону (месяцы sea, через Новый год — c>по) и полу,
// ещё не показанный семье (seen — Set id). Первым идёт тот, чьё окно закончится раньше всех: возрастное или сезонное.
// В день 0 недели совета нет — утром приходит карточка новой недели. Дети родились в разное время — у каждой семьи свой порядок.
const inMonths = ([a, b], m) => a <= b ? m >= a && m <= b : m >= a || m <= b;
const weeksLeftInSeason = ([, b], iso) => {
  const y = Number(iso.slice(0, 4)), m = Number(iso.slice(5, 7)), endY = b >= m ? y : y + 1;
  return (Date.UTC(endY, b, 0) - Date.parse(iso + "T00:00:00Z")) / (7 * 864e5);
};
export function pickTip(kid, todayISO, seen = new Set()){
  if (!kid?.birth) return null;
  const a = ageOf(kid.birth, todayISO), m = Number(todayISO.slice(5, 7));
  if (a.days < 0 || a.week > 52 || !a.dayOfWeek) return null;
  let best = null, bestLeft = Infinity;
  for (const t of DAY_TIPS) {
    if (seen.has(t.id) || a.week < t.from || a.week > t.to || (t.sea && !inMonths(t.sea, m)) || (t.sex && kid.sex && t.sex !== kid.sex)) continue;
    const left = Math.min(t.to - a.week, t.sea ? weeksLeftInSeason(t.sea, todayISO) : Infinity);
    if (left < bestLeft) { best = t; bestLeft = left; }
  }
  return best;
}

export function plural(n, one, few, many){
  const a=Math.abs(n)%100, b=a%10;
  if(a>10&&a<20) return many; if(b===1) return one; if(b>=2&&b<=4) return few; return many;
}
export function ageLabel(n){
  const days=(n-1)*7;
  if(n<=8) return `${days}–${days+6} дн`;
  return `≈${(days/30.44).toFixed(1).replace(".",",")} мес`;
}

