// Простое склонение имени: дательный («Рите 3 месяца») и родительный («Первый год Риты»).
const HUSH = /[гкхжшщч]$/i;
export function dative(name){
  const n = (name||"").trim(); if(!n) return n;
  if (/ия$/i.test(n)) return n.slice(0,-1)+"и";
  if (/[ая]$/i.test(n)) return n.slice(0,-1)+"е";
  if (/[йь]$/i.test(n)) return n.slice(0,-1)+"ю";
  if (/[бвгдзклмнпрстфхцчшщж]$/i.test(n)) return n+"у";
  return n;
}
export function genitive(name){
  const n = (name||"").trim(); if(!n) return n;
  if (/ия$/i.test(n)) return n.slice(0,-1)+"и";
  if (/а$/i.test(n)) return n.slice(0,-1) + (HUSH.test(n.slice(0,-1)) ? "и" : "ы");
  if (/я$/i.test(n)) return n.slice(0,-1)+"и";
  if (/[йь]$/i.test(n)) return n.slice(0,-1)+"я";
  if (/[бвгдзклмнпрстфхцчшщж]$/i.test(n)) return n+"а";
  return n;
}

