// Позже, в план не ставим (зависит от пола или далеко): ВПЧ девочкам 12–13 лет (одна доза, бесплатно), АДП-М в 16 лет, затем каждые 10 лет.
export const VACCINES_LATER = "Дальше по календарю: ВПЧ девочкам в 12–13 лет (одна доза, бесплатно), АДП-М в 16 лет и потом каждые 10 лет.";
export const VSTATUS = {planned:"по плану", booked:"записались", done:"сделано", skip:"не планируем"};
// Дата + месяцы без перескока через конец месяца (31 января + 1 мес = 28/29 февраля).
export function addMonthsISO(iso, k){
  const [y,m,d] = iso.split("-").map(Number);
  const last = new Date(Date.UTC(y, m-1+k+1, 0)).getUTCDate();
  return new Date(Date.UTC(y, m-1+k, Math.min(d, last))).toISOString().slice(0,10);
}
export const vaccineDate = (birth, at) => at.m ? addMonthsISO(birth, at.m) : new Date(Date.parse(birth+"T00:00:00Z") + at.d*864e5).toISOString().slice(0,10);
// План по календарю от даты рождения.
export const vaccinePlan = birth => VACCINES.map(v => ({code:v.code, kind:v.kind, name:v.name, planned:vaccineDate(birth, v.at)}));
// Когда напоминать: для записи — дата записи, иначе — плановая.
export const vaccineDue = v => (v.status === "booked" && v.booked_at ? v.booked_at.slice(0,10) : v.planned) || null;
export const vaccineKind = code => VACCINES.find(v => v.code === code)?.kind || "own";

// ---------- Вес по нормам ВОЗ ----------
// WHO Child Growth Standards, weight-for-age, LMS по месяцам 0–12 (таблицы ВОЗ в выгрузке CDC:
// ftp.cdc.gov/pub/Health_Statistics/NCHS/growthcharts/WHO-Girls-Weight-for-age Percentiles.csv и WHO-Boys-…).
// Для недель — линейная интерполяция L, M, S по возрасту в месяцах.
export const WHO_WFA = {
  girl: [[0.3809,3.2322,0.14171],[0.1714,4.1873,0.13724],[0.0962,5.1282,0.13],[0.0402,5.8458,0.12619],[-0.005,6.4237,0.12402],[-0.043,6.8985,0.12274],[-0.0756,7.297,0.12204],[-0.1039,7.6422,0.12178],[-0.1288,7.9487,0.12181],[-0.1507,8.2254,0.12199],[-0.17,8.48,0.12223],[-0.1872,8.7192,0.12247],[-0.2024,8.9481,0.12268]],
  boy:  [[0.3487,3.3464,0.14602],[0.2297,4.4709,0.13395],[0.197,5.5675,0.12385],[0.1738,6.3762,0.11727],[0.1553,7.0023,0.11316],[0.1395,7.5105,0.1108],[0.1257,7.934,0.10958],[0.1134,8.297,0.10902],[0.1021,8.6151,0.10882],[0.0917,8.9014,0.10881],[0.082,9.1649,0.10891],[0.073,9.4122,0.10906],[0.0644,9.6479,0.10925]],
};
const lmsAt = (sex, months) => {
  const t = WHO_WFA[sex] || WHO_WFA.girl, m = Math.max(0, Math.min(12, months)), i = Math.min(11, Math.floor(m)), u = m - i;
  return t[i].map((v, k) => v + (t[i + 1][k] - v) * u);
};
export const Z = {p3:-1.881, p15:-1.036, p50:0, p85:1.036, p97:1.881};
// вес (кг) на заданном z для возраста в днях
export function whoWeight(sex, days, z){
  const [L, M, S] = lmsAt(sex, days / 30.4375);
  return L === 0 ? M * Math.exp(S * z) : M * Math.pow(1 + L * S * z, 1 / L);
}
// перцентиль замера: z = ((X/M)^L − 1)/(L·S), затем нормальное распределение
export function weightPercentile(sex, days, kg){
  const [L, M, S] = lmsAt(sex, days / 30.4375);
  const z = L === 0 ? Math.log(kg / M) / S : (Math.pow(kg / M, L) - 1) / (L * S);
  const t = 1 / (1 + 0.2316419 * Math.abs(z)), d = 0.3989423 * Math.exp(-z * z / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  return {z, pct: Math.round((z > 0 ? 1 - p : p) * 1000) / 10};
}

