// Год сезона, если дата iso (ГГГГ-ММ-ДД) внутри окна {from, to}; иначе null.
export function noticeSeason(win, iso){
  const md = iso.slice(5, 10), y = Number(iso.slice(0, 4));
  if (win.from <= win.to) return md >= win.from && md <= win.to ? y : null;
  return md >= win.from ? y : md <= win.to ? y - 1 : null;
}
// Климат-чек: температура и влажность → вердикт. Пустое поле не оценивается.
export function climateVerdict(t, h){
  const out = [];
  if (Number.isFinite(t)) out.push(t > 22 ? "Жарко: убавь отопление или проветри" : t > 20 ? "Тепло: можно чуть прохладнее" : t < 18 ? "Прохладно: одень теплее, не грей комнату" : "");
  if (Number.isFinite(h)) out.push(h < 40 ? "Сухо: включи увлажнитель" : h > 70 ? "Сыро: проветри, нужен осушитель" : h > 60 ? "Влажность высоковата, но допустимо" : "");
  const bad = out.filter(Boolean);
  if (!bad.length) return Number.isFinite(t) && Number.isFinite(h) ? "Норма: так и держи" : Number.isFinite(t) || Number.isFinite(h) ? "Норма" : "";
  return bad.join(" · ");
}

// Скачки развития по неделям — схема «Чудесных недель» (van de Rijt, Plooij) в том виде, как её публикуют для родителей.
// Буква на неделю: c — спокойное время, g — хорошее настроение, l — скачок развития, a — возможна тревожность. LEAP_PEAKS — пики.
const LEAP_ROW = "cccclgcllgclgc" + "lllllcgcllllcc" + "aagccllllcgccl" + "llllccgclllllc" + "cgclllllclcccc" + "cllllgcc";
export const LEAP_WEEKS = LEAP_ROW.length;   // 78
export const LEAP_PEAKS = [5, 8, 12, 17, 26, 31, 36, 44, 54, 62, 73];
export const leapOf = n => n >= 1 && n <= LEAP_ROW.length ? {k:LEAP_ROW[n - 1], peak:LEAP_PEAKS.includes(n)} : null;
export const LEAP_KIND = {
  c:{name:"Спокойное время", d:"Обычная неделя: режим держится, можно спокойно пробовать новое."},
  g:{name:"Хорошее настроение", d:"Обычно весёлая и любопытная — хорошее время для новых игр, прогулок и гостей."},
  l:{name:"Скачок развития", d:"Может чаще плакать, проситься на руки и к груди, хуже спать. Это временно: больше близости и спокойный режим помогают."},
  a:{name:"Возможна тревожность", d:"Может сильнее держаться за маму и пугаться чужих. Помогают близость и предсказуемый день."},
};
export const LEAP_PEAK = "Пик скачка развития";
export const LEAP_NOTE = "Схема — по наблюдениям авторов книги «Чудесные недели». Недели в ней считают от предполагаемой даты родов: если малыш родился раньше или позже срока, всё сдвигается на эту разницу. Исследования эти сроки не подтвердили — это ориентир, а не норма.";
